async (page) => {
const F=globalThis.__fit; const {rows,metrics,mono3,basisOf,U,wls,labs,lab,de2000}=F; const N=rows.length;
const Bfull=U.map(u=>basisOf(u,mono3));
const W=[3,4,5].map(ch=>rows.map(r=>Math.pow(r[ch]/100,-4/3)));
const T=[3,4,5].map(ch=>rows.map(r=>r[ch]));
// active sets per channel: indices into mono3
let act=[mono3.map((_,i)=>i),mono3.map((_,i)=>i),mono3.map((_,i)=>i)];
function fitCh(ch,idx){const B=Bfull.map(b=>idx.map(i=>b[i]));return wls(B,T[ch],W[ch]);}
function predAll(coefs){return Bfull.map(b=>[0,1,2].map(ch=>{let s=0;act[ch].forEach((i,t)=>s+=coefs[ch][t]*b[i]);return s;}));}
let coefs=[0,1,2].map(ch=>fitCh(ch,act[ch]));
const curve=[];
let m=metrics(predAll(coefs));curve.push([60,m.mean,m.max]);
const score=(m)=>m.mean+0.25*m.max;
for(let step=0;step<45;step++){
  let best=null;
  for(let ch=0;ch<3;ch++){for(let t=0;t<act[ch].length;t++){
    const idx=act[ch].filter((_,k)=>k!==t);const cf=fitCh(ch,idx);
    const saved=[act[ch],coefs[ch]];act[ch]=idx;coefs[ch]=cf;
    const mm=metrics(predAll(coefs));
    act[ch]=saved[0];coefs[ch]=saved[1];
    const sc=score(mm);if(!best||sc<best.sc)best={sc,ch,t,mm};
  }}
  act[best.ch]=act[best.ch].filter((_,k)=>k!==best.t);coefs[best.ch]=fitCh(best.ch,act[best.ch]);
  const n=act[0].length+act[1].length+act[2].length;
  curve.push([n,best.mm.mean,best.mm.max]);
  if(best.mm.mean>0.8)break;
}
globalThis.__fit.act=act;
return JSON.stringify({curve,act:act.map(a=>a.map(i=>mono3[i].join('')))});
}
